FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'qa_measures_count') AND w.code = 'ATV-A-704E-08' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'einzelbestimmungen', 'Mehrfachbestimmung — Einzelwerte (je Zeile: Parameter, Datum, Einzelergebnis, Einheit)', 'json', NULL, false, 'IGC-Card 3', 'Plan 3: Zeilen je Einzelbestimmung der Mehrfachbestimmung (IQC-Karte 3 Spalten 4–6); Anzahl → n_determinations_calc (ATV-A-704E-09-D1), Mittelwert → mean_value_calc (-D2, EQ-01-Mathematik über die Zeilen), größte Abweichung vom Mittelwert → max_dev_pct_calc (-D3, EQ-02-Mathematik maximiert). Sichtbar nur, wenn multiple_determination_performed angekreuzt ist (§4.4). Die Einzelfelder single_result_i / n_determinations / mean_value / deviation_single_pct bleiben (atv_a704e-D-1 … D-5); EQ-01 … EQ-06 bleiben unverändert (atv_a704e-R-1).', 'imported_unverified', 'IQC-Card 3 - Multiple Determinations (form header): 1 Date | 2 Name | 3 Sample designation | 4 Measured value 1 [mg/l] | 5 Measured value 2 [mg/l] | 6 Measured value 3 [mg/l] | 7 Mean [mg/l] | 8 Greatest spread Difference [mg/l] | 9 Greatest spread Col 8 x 100% / Col 7 [%] | 10 Interpretation: Quality target achieved? — printed p.30 — From the single results a mean value must be produced, which represents the measuring result. Here, all single results must be included in the mean. | From the single measured values the mean (add single measured values and divide them by the number of the measured values; column 7) is produced. | IQC-Card 3 - Multiple Determinations (form header): 1 Date | 2 Name | 3 Sample designation | 4 Measured value 1 [mg/l] | 5 Measured value 2 [mg/l] | 6 Measured value 3 [mg/l] | 7 Mean [mg/l] | 8 Greatest spread Difference [mg/l] | 9 Greatest spread Col 8 x 100% / Col 7 [%] | 10 Interpretation: Quality target achieved? — printed p.29 and 30 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'register', '{"title":"Mehrfachbestimmung (IQC-Karte 3)","subtitle":"je Einzelbestimmung eine Zeile — Mittelwert, Anzahl und größte Abweichung werden aus den Zeilen berechnet","add_label":"+ Einzelwert","placement":"section","columns":[{"key":"parameter","label":"Parameter","type":"enum","options":["settable_substances","bod5","cod","nh4_n","no3_n","no2_n","p_total","tn","toc"],"option_labels":{"settable_substances":"Absetzbare Stoffe","bod5":"BSB5","cod":"CSB","nh4_n":"NH4-N (Ammoniumstickstoff)","no3_n":"NO3-N (Nitratstickstoff)","no2_n":"NO2-N (Nitritstickstoff)","p_total":"Pges (Gesamtphosphor)","tn":"TNb / Nges (Gesamtstickstoff, gebunden)","toc":"TOC (gesamter organischer Kohlenstoff)"},"required":true,"discriminator":true,"aria_label":"Analytischer Parameter der Mehrfachbestimmung (IQC-Karte 3 Spalte 4)"},{"key":"date","label":"Datum","type":"date","required":true,"aria_label":"Datum der Bestimmung (IQC-Karte 3 Spalte 1)"},{"key":"single_result","label":"Einzelergebnis","type":"number","required":true,"aria_label":"Einzelner Messwert der Mehrfachbestimmung (IQC-Karte 3 Spalten 4 bis 6)"},{"key":"unit","label":"Einheit","type":"text","placeholder":"mg/l","aria_label":"Einheit des Messwertes (IQC-Karte 3 druckt mg/l)"}],"footer":["n_determinations_calc","mean_value_calc","max_dev_pct_calc"],"note":"Je Einzelbestimmung eine Zeile; prod hält single_result_i genau einmal (atv_a704e-D-1). Anzahl → n_determinations_calc, Mittelwert → mean_value_calc (die gespeicherte EQ-01-Mathematik über die Zeilen), größte Abweichung vom Mittelwert in % → max_dev_pct_calc (die gespeicherte EQ-02-Mathematik, über alle Zeilen maximiert). **Eine Abweichungsspalte JE ZEILE ist im Rechenwerk nicht ausdrückbar** — ein Zeilenausdruck kann kein Aggregat seines eigenen Registers lesen (atv_a704e-F-1). Ein leeres Register liefert nie eine Phantom-0: die Mittelwert- und Abweichungszeilen sind dann „manuell erforderlich“. Achtung (atv_a704e-J-1): die prod-Zelle beschreibt die gedruckte Spalte 9 als „greatest difference of the single measured values divided by the mean value“ — eine größte SPANNWEITE, nicht die Abweichung eines Einzelwertes; gespeichert ist EQ-02 als Einzelwert-Abweichung. Text der prod-Zelle: The greatest difference in the single measured values is entered into the IQC-Card in mg/l (column 8) and in % (greatest difference of the single measured values divided by the mean value; column 9). In column 10 the result of the control measure is documented. | IQC-Card 3 - Multiple Determinations (form header): 1 Date | 2 Name | 3 Sample designation | 4 Measured value 1 [mg/l] | 5 Measured value 2 [mg/l] | 6 Measured value 3 [mg/l] | 7 Mean [mg/l] | 8 Greatest spread Difference [mg/l] | 9 Greatest spread Col 8 x 100% / Col 7 [%] | 10 Interpretation: Quality target achieved? — printed p.29 and 30 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]"}'::jsonb, NULL, 'multiple_determination_performed == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'einzelbestimmungen') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
