FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'n_determinations_calc') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
