SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'max_dev_pct_calc', 'Größte Abweichung eines Einzelwertes vom Mittelwert (aus dem Register)', 'number', '%', false, 'IGC-Card 3', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-09-D3 — die gespeicherte EQ-02-Mathematik (100 * (single_result_i − mean_value) / mean_value), über alle Zeilen maximiert (max(max − Mittelwert, Mittelwert − min) * 100 / Mittelwert). Eine Abweichungsspalte je Zeile ist nicht ausdrückbar (atv_a704e-F-1); die gedruckte Spalte 9 der IQC-Karte 3 beschreibt eine größte SPANNWEITE ÷ Mittelwert — die Abweichung von der gespeicherten Formel ist atv_a704e-J-1. Grundlage des STAGED Gate-Vorschlags zu CR-019 (atv_a704e-G-2).', 'imported_unverified', 'The greatest difference in the single measured values is entered into the IQC-Card in mg/l (column 8) and in % (greatest difference of the single measured values divided by the mean value; column 9). In column 10 the result of the control measure is documented. | IQC-Card 3 - Multiple Determinations (form header): 1 Date | 2 Name | 3 Sample designation | 4 Measured value 1 [mg/l] | 5 Measured value 2 [mg/l] | 6 Measured value 3 [mg/l] | 7 Mean [mg/l] | 8 Greatest spread Difference [mg/l] | 9 Greatest spread Col 8 x 100% / Col 7 [%] | 10 Interpretation: Quality target achieved? — printed p.29 and 30 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, 'multiple_determination_performed == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'max_dev_pct_calc') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'verduennungsversuche', 'Verdünnungsversuche (je Zeile: Probenvolumen, Gesamtvolumen, Messwert verdünnt → berechneter Wert, Abweichung)', 'json', NULL, false, 'IGC-Card 5, Sheet 1', 'Plan 3: Zeilen je Verdünnungsversuch (IQC-Karte 5 Blatt 1); der berechnete Wert je Zeile ist die gespeicherte EQ-03-Mathematik, die Abweichung der Vergleich mit dem Messwert der Originalprobe; größte Abweichung → dilution_max_dev (ATV-A-704E-09-D4). Die Einzelfelder sample_volume / total_volume / measured_value_diluted_sample / calculated_value / measured_value_original_sample bleiben (atv_a704e-D-6 … D-10); EQ-03 bleibt unverändert (atv_a704e-R-1).', 'imported_unverified', 'IQC-Card 5, Sheet 1 - Dilution: 2. Single steps: a) Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3) b) Dilution c) Determination of MEASURED VALUE DILUTED SAMPLE (column 5) | 3. Formulas for calculation: DILUTION FACTOR (column 4) = TOTAL VOLUME / SAMPLE VOLUME. CALCULATED VALUE (column 6) = DILUTION FACTOR · MEASURED VALUE DILUTED SAMPLE — printed p.35 — IQC-Card 5, Sheet 1 - Dilution: 2. Single steps: a) Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3) b) Dilution c) Determination of MEASURED VALUE DILUTED SAMPLE (column 5) | 3. Formulas for calculation: DILUTION FACTOR (column 4) = TOTAL VOLUME / SAMPLE VOLUME. CALCULATED VALUE (column 6) = DILUTION FACTOR · MEASURED VALUE DILUTED SAMPLE | If the variation between CALCULATED VALUE and MEASURED VALUE ORIGINAL SAMPLE is smaller than given in the internal specification (IQC-Card 2), there is no error in the matrix. If it is greater, an error in the matrix is likely. — printed p.35 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'register', '{"title":"Verdünnungsversuche (IQC-Karte 5, Blatt 1)","subtitle":"je Verdünnungsversuch eine Zeile — Verdünnungsfaktor, berechneter Wert und Abweichung vom Messwert der Originalprobe werden je Zeile berechnet","add_label":"+ Verdünnungsversuch","placement":"section","columns":[{"key":"parameter","label":"Parameter","type":"enum","options":["settable_substances","bod5","cod","nh4_n","no3_n","no2_n","p_total","tn","toc"],"option_labels":{"settable_substances":"Absetzbare Stoffe","bod5":"BSB5","cod":"CSB","nh4_n":"NH4-N (Ammoniumstickstoff)","no3_n":"NO3-N (Nitratstickstoff)","no2_n":"NO2-N (Nitritstickstoff)","p_total":"Pges (Gesamtphosphor)","tn":"TNb / Nges (Gesamtstickstoff, gebunden)","toc":"TOC (gesamter organischer Kohlenstoff)"},"aria_label":"Analytischer Parameter des Verdünnungsversuchs"},{"key":"date","label":"Datum","type":"date","aria_label":"Datum des Verdünnungsversuchs"},{"key":"sample_volume_ml","label":"Probenvolumen","type":"number","unit":"ml","required":true,"aria_label":"Probenvolumen vor der Verdünnung (IQC-Karte 5 Blatt 1, Nenner des Verdünnungsfaktors)"},{"key":"total_volume_ml","label":"Gesamtvolumen","type":"number","unit":"ml","required":true,"aria_label":"Gesamtvolumen nach der Verdünnung (IQC-Karte 5 Blatt 1, Zähler des Verdünnungsfaktors)"},{"key":"measured_diluted","label":"Messwert verdünnte Probe","type":"number","required":true,"aria_label":"Messwert der verdünnten Probe (IQC-Karte 5 Blatt 1 Spalte 5)"},{"key":"calculated","label":"Berechneter Wert","type":"derived","expr":"total_volume_ml / sample_volume_ml * measured_diluted"},{"key":"reference","label":"Messwert Originalprobe","type":"number","required":true,"aria_label":"Messwert der Originalprobe (IQC-Karte 5 Blatt 1 Spalte 3) — Vergleichswert"},{"key":"dev_pct","label":"Abweichung","type":"derived","expr":"(calculated - reference) / reference * 100"}],"footer":["dilution_max_dev"],"note":"Je Versuch eine Zeile; der berechnete Wert ist die gespeicherte EQ-03-Mathematik (Gesamtvolumen / Probenvolumen × Messwert verdünnte Probe), die Abweichung der prozentuale Vergleich mit dem Messwert der Originalprobe. Der Messwert der Originalprobe ist PFLICHT, damit jede vollständige Zeile eine berechenbare Abweichung hat (sonst wäre die Maximumsbildung „manuell erforderlich“). Die zulässige Abweichung steht in der internen Vorgabe (IQC-Karte 2) — sie ist hier keine hinterlegte Tabelle (atv_a704e-U-1). Text der prod-Zelle: IQC-Card 5, Sheet 1 - Dilution: 2. Single steps: a) Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3) b) Dilution c) Determination of MEASURED VALUE DILUTED SAMPLE (column 5) | 3. Formulas for calculation: DILUTION FACTOR (column 4) = TOTAL VOLUME / SAMPLE VOLUME. CALCULATED VALUE (column 6) = DILUTION FACTOR · MEASURED VALUE DILUTED SAMPLE | If the variation between CALCULATED VALUE and MEASURED VALUE ORIGINAL SAMPLE is smaller than given in the internal specification (IQC-Card 2), there is no error in the matrix. If it is greater, an error in the matrix is likely. — printed p.35 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verduennungsversuche') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'dilution_max_dev', 'Größte Abweichung der Verdünnungsversuche (aus dem Register)', 'number', '%', false, 'IGC-Card 5, Sheet 1', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-09-D4 (max_rows über verduennungsversuche, |Abweichung|); leeres Register ⇒ manuell erforderlich, nie 0. Grundlage des STAGED Gate-Vorschlags zur Plausibilitätsprüfung (atv_a704e-G-5).', 'imported_unverified', 'IQC-Card 5, Sheet 1 - Dilution: 2. Single steps: a) Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3) b) Dilution c) Determination of MEASURED VALUE DILUTED SAMPLE (column 5) | 3. Formulas for calculation: DILUTION FACTOR (column 4) = TOTAL VOLUME / SAMPLE VOLUME. CALCULATED VALUE (column 6) = DILUTION FACTOR · MEASURED VALUE DILUTED SAMPLE | If the variation between CALCULATED VALUE and MEASURED VALUE ORIGINAL SAMPLE is smaller than given in the internal specification (IQC-Card 2), there is no error in the matrix. If it is greater, an error in the matrix is likely. — printed p.35 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'dilution_max_dev') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'aufstockungsversuche', 'Aufstockungsversuche (je Zeile: Volumina, Standardkonzentration, Messwerte → NSS, Abweichung)', 'json', NULL, false, 'IGC-Card 5, Sheet 3', 'Plan 3: Zeilen je Standardaddition (IQC-Karte 5 Blatt 3); NSS je Zeile ist die gespeicherte EQ-04-Mathematik, die Abweichung der Vergleich des Messwertes der aufgestockten Probe mit NSS; größte Abweichung → spike_max_dev (ATV-A-704E-09-D5). Die Einzelfelder volume_sample / volume_standard / concentration_standard / measured_value_original_sample / measured_value_spiked_sample / NSS bleiben (atv_a704e-D-11 … D-16); EQ-04 bleibt unverändert (atv_a704e-R-1).', 'imported_unverified', 'IQC-Card 5, Sheet 3 - standard addition (general procedure): 2. Single steps: Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3), Standard addition by adding the VOLUME STANDARD (column 5) in familiar CONCENTRATION STANDARD (column 6) to the defined VOLUME SAMPLE (column 4), Determination of MEASURED VALUE SPIKED SAMPLE (column 9). | 3. Calculation: NOMINAL VALUE SPIKED SAMPLE (NSS, column 8): NSS = [(volume sample · measured value original sample) + (volume standard · concentration standard)] / (volume sample + volume standard) — printed p.36 — If the measured value MEASURED VALUE SPIKED SAMPLE deviates from the NOMINAL VALUE SPIKED SAMPLE by more than the tolerance given in the internal specification (IQC-Card 2), a matrix error is likely. — printed p.36 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'register', '{"title":"Aufstockungsversuche / Standardaddition (IQC-Karte 5, Blatt 3)","subtitle":"je Aufstockung eine Zeile — Sollwert der aufgestockten Probe (NSS) und Abweichung des Messwertes werden je Zeile berechnet","add_label":"+ Aufstockungsversuch","placement":"section","columns":[{"key":"parameter","label":"Parameter","type":"enum","options":["settable_substances","bod5","cod","nh4_n","no3_n","no2_n","p_total","tn","toc"],"option_labels":{"settable_substances":"Absetzbare Stoffe","bod5":"BSB5","cod":"CSB","nh4_n":"NH4-N (Ammoniumstickstoff)","no3_n":"NO3-N (Nitratstickstoff)","no2_n":"NO2-N (Nitritstickstoff)","p_total":"Pges (Gesamtphosphor)","tn":"TNb / Nges (Gesamtstickstoff, gebunden)","toc":"TOC (gesamter organischer Kohlenstoff)"},"aria_label":"Analytischer Parameter der Standardaddition"},{"key":"date","label":"Datum","type":"date","aria_label":"Datum der Standardaddition"},{"key":"sample_volume_ml","label":"Volumen Probe","type":"number","unit":"ml","required":true,"aria_label":"Volumen der Probe in der Standardaddition (IQC-Karte 5 Blatt 3 Spalte 4)"},{"key":"standard_volume_ml","label":"Volumen Standard","type":"number","unit":"ml","required":true,"aria_label":"Volumen der zugesetzten Standardlösung (IQC-Karte 5 Blatt 3 Spalte 5)"},{"key":"standard_concentration","label":"Konzentration Standard","type":"number","required":true,"aria_label":"Konzentration der zugesetzten Standardlösung (IQC-Karte 5 Blatt 3 Spalte 6)"},{"key":"measured_original","label":"Messwert Originalprobe","type":"number","required":true,"aria_label":"Messwert der Originalprobe (IQC-Karte 5 Blatt 3 Spalte 3)"},{"key":"measured_spiked","label":"Messwert aufgestockte Probe","type":"number","required":true,"aria_label":"Messwert der aufgestockten Probe (IQC-Karte 5 Blatt 3 Spalte 9)"},{"key":"nss_nominal","label":"Sollwert aufgestockte Probe (NSS)","type":"derived","expr":"(sample_volume_ml * measured_original + standard_volume_ml * standard_concentration) / (sample_volume_ml + standard_volume_ml)"},{"key":"dev_pct","label":"Abweichung","type":"derived","expr":"(measured_spiked - nss_nominal) / nss_nominal * 100"}],"footer":["spike_max_dev"],"note":"Je Aufstockung eine Zeile; der Sollwert NSS ist die gespeicherte EQ-04-Mathematik, die Abweichung der prozentuale Vergleich des Messwertes der aufgestockten Probe mit dem Sollwert. Die zulässige Toleranz steht in der internen Vorgabe (IQC-Karte 2) — hier keine hinterlegte Tabelle (atv_a704e-U-1). Achtung X-2: prod führt dieselbe physikalische Größe zweimal — sample_volume (Blatt 1) und volume_sample (Blatt 3); die beiden Register halten sie getrennt, wie die beiden Blätter es drucken. Text der prod-Zelle: IQC-Card 5, Sheet 3 - standard addition (general procedure): 2. Single steps: Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3), Standard addition by adding the VOLUME STANDARD (column 5) in familiar CONCENTRATION STANDARD (column 6) to the defined VOLUME SAMPLE (column 4), Determination of MEASURED VALUE SPIKED SAMPLE (column 9). | 3. Calculation: NOMINAL VALUE SPIKED SAMPLE (NSS, column 8): NSS = [(volume sample · measured value original sample) + (volume standard · concentration standard)] / (volume sample + volume standard) — printed p.36 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'aufstockungsversuche') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'spike_max_dev', 'Größte Abweichung der Aufstockungsversuche (aus dem Register)', 'number', '%', false, 'IGC-Card 5, Sheet 3', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-09-D5 (max_rows über aufstockungsversuche, |Abweichung|); leeres Register ⇒ manuell erforderlich, nie 0. Grundlage des STAGED Gate-Vorschlags zur Plausibilitätsprüfung (atv_a704e-G-5).', 'imported_unverified', 'If the measured value MEASURED VALUE SPIKED SAMPLE deviates from the NOMINAL VALUE SPIKED SAMPLE by more than the tolerance given in the internal specification (IQC-Card 2), a matrix error is likely. — printed p.36 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'spike_max_dev') AND w.code = 'ATV-A-704E-09' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'vergleichsmessungen', 'Vergleichsmessungen (je Zeile: Art, Parameter, Datum, Messwert Betriebsverfahren, Soll-/Referenzwert → Abweichung)', 'json', NULL, false, 'IGC-Card 6, IGC-Card 7', 'Plan 3: Zeilen je Gleichwertigkeitsmessung (IQC-Karte 6) bzw. Parallelanalyse (IQC-Karte 7) mit der Art als Zeilentyp; die Abweichung je Zeile ist die gespeicherte EQ-05- / EQ-06-Mathematik (identische Form, unterschiedlicher Bezugswert); größte Abweichung je Art → equivalency_max_dev (ATV-A-704E-10-D1) / parallel_max_dev (-D2). Sichtbar, wenn Gleichwertigkeits- oder Parallelmessungen durchgeführt werden (§4.4). Die Einzelfelder measured_value_operating / nominal_value_reference / measured_value_reference / deviation_equivalency_pct / deviation_parallel_pct bleiben (atv_a704e-D-17 … D-21); EQ-05 / EQ-06 bleiben unverändert (atv_a704e-R-1).', 'imported_unverified', 'IQC-Card 6 - Equivalency Measurements (form header): 1 Date | 2 Name | 3 Sample designation | 4 Parameter | 5 Mean [mg/l] | 6 Nominal value or mean of the equivalency measurements [mg/l] | 7 Deviation of the mean from the nominal value [mg/l] | 8 Deviation relative [%] | 9 Interpretation: Quality target achieved? — printed p.45 — IQC-Card 7 - Parallel Measurements to the Reference Method (form header): 7 Referenced monitoring Measured value [mg/l] | 8 Measured value of the operating method [mg/l] | 9 Deviation absolute Col8-Col7 [mg/l] | 10 Deviation relative Col9 x 100/Col7 [%] | 11/12 Permissible deviation Condition [mg/l] [%] | 13 Interpretation: Quality target achieved? — printed p.48 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'register', '{"title":"Vergleichsmessungen (IQC-Karte 6 Gleichwertigkeit / IQC-Karte 7 Parallelanalysen)","subtitle":"je Vergleichsmessung eine Zeile — Art der Messung als Zeilentyp; die prozentuale Abweichung wird je Zeile berechnet","add_label":"+ Vergleichsmessung","placement":"section","columns":[{"key":"kind","label":"Art","type":"enum","options":["equivalency","parallel"],"option_labels":{"equivalency":"Gleichwertigkeitsmessung (IQC-Karte 6)","parallel":"Parallelanalyse zur Referenzmethode (IQC-Karte 7)"},"required":true,"discriminator":true,"aria_label":"Art der Vergleichsmessung (Gleichwertigkeit oder Parallelanalyse)"},{"key":"parameter","label":"Parameter","type":"enum","options":["settable_substances","bod5","cod","nh4_n","no3_n","no2_n","p_total","tn","toc"],"option_labels":{"settable_substances":"Absetzbare Stoffe","bod5":"BSB5","cod":"CSB","nh4_n":"NH4-N (Ammoniumstickstoff)","no3_n":"NO3-N (Nitratstickstoff)","no2_n":"NO2-N (Nitritstickstoff)","p_total":"Pges (Gesamtphosphor)","tn":"TNb / Nges (Gesamtstickstoff, gebunden)","toc":"TOC (gesamter organischer Kohlenstoff)"},"aria_label":"Analytischer Parameter der Vergleichsmessung (IQC-Karte 6 Spalte 4)"},{"key":"date","label":"Datum","type":"date","aria_label":"Datum der Vergleichsmessung (IQC-Karte 6 Spalte 1)"},{"key":"operating_value","label":"Messwert Betriebsverfahren","type":"number","required":true,"aria_label":"Messwert des Betriebsverfahrens, meist Mittelwert (IQC-Karte 6 Spalte 5 / IQC-Karte 7 Spalte 8)"},{"key":"reference_value","label":"Soll- bzw. Referenzwert","type":"number","required":true,"aria_label":"Sollwert der Gleichwertigkeitsmessung (IQC-Karte 6 Spalte 6) bzw. Messwert der Referenzmethode (IQC-Karte 7 Spalte 7)"},{"key":"dev_pct","label":"Abweichung","type":"derived","expr":"(operating_value - reference_value) / reference_value * 100"}],"footer":["equivalency_max_dev","parallel_max_dev"],"note":"Ein Register mit Zeilentyp statt zweier Register: die gespeicherten EQ-05 und EQ-06 haben dieselbe Form — (Messwert Betriebsverfahren − Bezugswert) / Bezugswert × 100 —, nur der Nenner heißt bei der Gleichwertigkeit „Sollwert“ (IQC-Karte 6 Spalte 6) und bei der Parallelanalyse „Messwert der Referenzmethode“ (IQC-Karte 7 Spalte 7); beide stehen in der Spalte „Soll- bzw. Referenzwert“. Eine ZWEITE Spalte „nominal_value“ wäre ein zweiter Nenner, den die Abweichung nicht liest — deshalb nicht angelegt (atv_a704e-J-2). Größte Abweichung je Art → equivalency_max_dev / parallel_max_dev; fehlt eine Art ganz, ist das Maximum „manuell erforderlich“, nie 0. Text der prod-Zellen: IQC-Card 6 - Equivalency Measurements (form header): 1 Date | 2 Name | 3 Sample designation | 4 Parameter | 5 Mean [mg/l] | 6 Nominal value or mean of the equivalency measurements [mg/l] | 7 Deviation of the mean from the nominal value [mg/l] | 8 Deviation relative [%] | 9 Interpretation: Quality target achieved? | Usually, the deviation in the central measurement range should not exceed the quality target of < 20 % (in this regard also see IQC-Card 2: Internal Specifications). — printed p.45 and 43 | IQC-Card 7 - Parallel Measurements to the Reference Method (form header): 7 Referenced monitoring Measured value [mg/l] | 8 Measured value of the operating method [mg/l] | 9 Deviation absolute Col8-Col7 [mg/l] | 10 Deviation relative Col9 x 100/Col7 [%] | 11/12 Permissible deviation Condition [mg/l] [%] | 13 Interpretation: Quality target achieved? | Usually, the deviation in the central measuring range should not exceed the quality target of < 20 % (see also IQC-Card 2 in this regard: Internal Specifications). Especially with measuring results in the lower concentration range (e. g. Ptotal < 1 mg/l) greater percental tolerances are possible. — printed p.48 and 46 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]"}'::jsonb, NULL, 'equivalency_check_performed == true OR parallel_analysis_performed == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'vergleichsmessungen') AND w.code = 'ATV-A-704E-10' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'equivalency_max_dev', 'Größte Abweichung der Gleichwertigkeitsmessungen (aus dem Register)', 'number', '%', false, 'IGC-Card 6', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-10-D1 (max_rows über vergleichsmessungen, |Abweichung|, nur Zeilen der Art Gleichwertigkeit); ohne solche Zeile „manuell erforderlich“, nie 0. Grundlage des STAGED Gate-Vorschlags zu CR-022 (atv_a704e-G-2).', 'imported_unverified', 'IQC-Card 6 - Equivalency Measurements (form header): 1 Date | 2 Name | 3 Sample designation | 4 Parameter | 5 Mean [mg/l] | 6 Nominal value or mean of the equivalency measurements [mg/l] | 7 Deviation of the mean from the nominal value [mg/l] | 8 Deviation relative [%] | 9 Interpretation: Quality target achieved? | Usually, the deviation in the central measurement range should not exceed the quality target of < 20 % (in this regard also see IQC-Card 2: Internal Specifications). — printed p.45 and 43 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, 'equivalency_check_performed == true OR parallel_analysis_performed == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'equivalency_max_dev') AND w.code = 'ATV-A-704E-10' AND s.code = 'ATV-A-704E';
