FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pruefmittel_count') AND w.code = 'ATV-A-704E-11' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'pipette_dev_max', 'Größte Pipettenabweichung (aus dem Register)', 'number', '%', false, 'Annex A, IQC-Card 9', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-11-D2 (max_rows über pruefmittel.pipette_dev_pct, nur Zeilen mit dem Prüfmittel Kolbenhubpipette); ohne Pipettenzeile „manuell erforderlich“, nie 0. Die volumenabhängige Grenze (2 % / 1 %) bleibt in CR-025 auf den Einzelfeldern — die Umstellung auf das Register ist STAGED (atv_a704e-G-3), die gedruckte Volumentabelle fehlt bis atv_a704e-U-3.', 'imported_unverified', 'The mean must be calculated from the 5 results of the weightings. [...] The mean value must lie within a defined tolerance range (see table). | Tested volume [ml] / Deviation [%] / Tolerance range [g]: 0.100 / ≤ 2 / 0.098 - 0.102 | 0.200 / ≤ 2 / 0.196 - 0.204 | 0.500 / ≤ 2 / 0.490 - 0.510 | 1.000 / ≤ 1 / 0.990 - 1.010 | 2.000 / ≤ 1 / 1.980 - 2.020 | 5.000 / ≤ 1 / 4.950 - 5.050 | If the results lie outside the tolerance range, the pipette must no longer be used as testing equipment (remove designation) and should be sent to the manufacturer for testing, if necessary. — printed p.55 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pipette_dev_max') AND w.code = 'ATV-A-704E-11' AND s.code = 'ATV-A-704E';
UPDATE fields f SET widget = 'attestation', ui_config = NULL, lookup = NULL, visible_when = 'testing_equipment == ''photometer''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'photometer_check_done' AND w.code = 'ATV-A-704E-11' AND s.code = 'ATV-A-704E' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'mitarbeiter', 'Personalnachweis (je Person: Name, Qualifikation, Einweisungsdatum, Schulungsnachweis)', 'json', NULL, false, 'Annex A, IQC-Card 10', 'Plan 3: Zeilen je Mitarbeiterin/Mitarbeiter (IQC-Karte 10 Blätter 1 und 2); Anzahl → mitarbeiter_count (ATV-A-704E-12-D2). Die Einzelfelder employee_qualification / instruction_training_record bleiben (atv_a704e-D-32 / D-33); CR-018 liest heute die Attestierung (atv_a704e-G-6).', 'imported_unverified', 'Qualification: Predominantly, qualification is certified by a corresponding vocational training. A training as "specialist on wastewater technology" or a similar training qualification should be listed here. A qualification that was gained otherwise must be presented in a corresponding way. — printed p.62 — Overview of instruction and training: This overview serves as a proof of training according to Section 4.3.3 of the Standard. Here the completed basic introduction as well as all internal and external successive training are recorded. Here, for example, also supportive visits by the manufacturer and DWA-courses must be registered. | Sheet 2 - Overview of Instructions and Training: 1 Event: topic and organising party | 2 Date | 3 Signature supervisor — printed p.62 and 66 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'register', '{"title":"Personalnachweis Betriebsanalytik (IQC-Karte 10)","subtitle":"je Mitarbeiterin/Mitarbeiter eine Zeile: Qualifikation, Einweisung, Schulungsnachweis","add_label":"+ Mitarbeiter","placement":"section","columns":[{"key":"name","label":"Name","type":"text","required":true,"aria_label":"Name der Mitarbeiterin bzw. des Mitarbeiters (IQC-Karte 10 Blatt 1)"},{"key":"qualification","label":"Qualifikation","type":"text","aria_label":"Qualifikation, in der Regel durch eine einschlägige Berufsausbildung belegt (IQC-Karte 10 Blatt 1)"},{"key":"instruction_date","label":"Datum der Einweisung","type":"date","aria_label":"Datum der Grundeinweisung bzw. der letzten Schulung (IQC-Karte 10 Blatt 2 Spalte 2)"},{"key":"training_record","label":"Einweisungs-/Schulungsnachweis","type":"text","aria_label":"Veranstaltung: Thema und Veranstalter (IQC-Karte 10 Blatt 2 Spalte 1)"}],"footer":["mitarbeiter_count"],"note":"Je Person eine Zeile — prod hält employee_qualification und instruction_training_record je genau einmal (atv_a704e-D-32 / D-33), sodass heute nur eine Person dokumentierbar ist. Text der prod-Zellen: Qualification: Predominantly, qualification is certified by a corresponding vocational training. A training as \"specialist on wastewater technology\" or a similar training qualification should be listed here. A qualification that was gained otherwise must be presented in a corresponding way. — printed p.62 | Overview of instruction and training: This overview serves as a proof of training according to Section 4.3.3 of the Standard. Here the completed basic introduction as well as all internal and external successive training are recorded. Here, for example, also supportive visits by the manufacturer and DWA-courses must be registered. | Sheet 2 - Overview of Instructions and Training: 1 Event: topic and organising party | 2 Date | 3 Signature supervisor — printed p.62 and 66 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'mitarbeiter') AND w.code = 'ATV-A-704E-12' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'mitarbeiter_count', 'Anzahl dokumentierter Mitarbeiter (aus dem Register)', 'number', NULL, false, 'Annex A, IQC-Card 10', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-12-D2 (count_rows über mitarbeiter; leeres Register ⇒ 0, nie ein Phantom-Pass); Grundlage des STAGED Gate-Vorschlags zu CR-018 (atv_a704e-G-6).', 'imported_unverified', 'Qualification: Predominantly, qualification is certified by a corresponding vocational training. A training as "specialist on wastewater technology" or a similar training qualification should be listed here. A qualification that was gained otherwise must be presented in a corresponding way. — printed p.62 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'mitarbeiter_count') AND w.code = 'ATV-A-704E-12' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'abweichungen', 'Abweichungsprotokoll (je Zeile: Datum, Merkmal, IQC-Karte, Ursache, Maßnahme, Ergebnis)', 'json', NULL, false, 'Annex A, IQC-Card 11', 'Plan 3: Zeilen je Abweichung (IQC-Karte 11 Spalten 1–9); Anzahl → abweichungen_count (ATV-A-704E-12-D1). Die Einzelfelder deviation_feature / deviation_cause / deviation_measure / deviation_iqc_card_ref bleiben (atv_a704e-D-34 … D-37); CR-028 (leere Bedingung) ist der STAGED Gate-Vorschlag atv_a704e-G-7.', 'imported_unverified', 'Here, the date of the deviation is put down in column 1. The name of the person who detects the deviation (column 2), the type of distinctive features (column 3) and in which IQC-Card they are documented (column 4) are also noted. As soon as the cause is known, it is documented in column 5 with the measured taken (column 6). The result of the measures introduced is entered together with date (date 7), the result of the measures (column 8) and the name of the person who determined the result (column 9). — printed p.67 — Here, the date of the deviation is put down in column 1. The name of the person who detects the deviation (column 2), the type of distinctive features (column 3) and in which IQC-Card they are documented (column 4) are also noted. As soon as the cause is known, it is documented in column 5 with the measured taken (column 6). The result of the measures introduced is entered together with date (date 7), the result of the measures (column 8) and the name of the person who determined the result (column 9). — printed p.67 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'register', '{"title":"Abweichungen und Maßnahmen (IQC-Karte 11)","subtitle":"je Abweichung eine Zeile: Merkmal, betroffene IQC-Karte, Ursache, Maßnahme, Ergebnis","add_label":"+ Abweichung","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","aria_label":"Datum der Abweichung (IQC-Karte 11 Spalte 1)"},{"key":"feature","label":"Auffälliges Merkmal","type":"text","required":true,"aria_label":"Art des auffälligen Merkmals (IQC-Karte 11 Spalte 3)"},{"key":"iqc_card_ref","label":"Dokumentiert in IQC-Karte","type":"enum","options":["card_1","card_2","card_3","card_4","card_5","card_6","card_7","card_8","card_9","card_10","card_11"],"option_labels":{"card_1":"Übersichtskarte","card_2":"Interne Vorgaben","card_3":"Mehrfachbestimmungen","card_4":"Messung von Standards","card_5":"Plausibilitätsprüfung (Verdünnung und Standardaddition)","card_6":"Gleichwertigkeitsmessungen","card_7":"Parallelanalysen zur Referenzmethode","card_8":"Probenahme und Probenvorbehandlung","card_9":"Prüfmittelüberwachung","card_10":"Personalnachweisblatt Betriebsanalytik","card_11":"Abweichungen und Maßnahmen"},"aria_label":"IQC-Karte, in der die Abweichung dokumentiert ist (IQC-Karte 11 Spalte 4)"},{"key":"cause","label":"Ursache","type":"text","aria_label":"Ermittelte Ursache der Abweichung (IQC-Karte 11 Spalte 5)"},{"key":"measure","label":"Maßnahme","type":"text","aria_label":"Eingeleitete Maßnahme (IQC-Karte 11 Spalte 6)"},{"key":"result","label":"Ergebnis der Maßnahme","type":"text","aria_label":"Ergebnis der eingeleiteten Maßnahme (IQC-Karte 11 Spalte 8)"}],"footer":["abweichungen_count"],"note":"Je Abweichung eine Zeile — prod hält deviation_feature / deviation_cause / deviation_measure / deviation_iqc_card_ref je genau einmal (atv_a704e-D-34 … D-37), sodass heute nur EINE Abweichung dokumentierbar ist; ein Abweichungsprotokoll braucht viele. Text der prod-Zelle: Here, the date of the deviation is put down in column 1. The name of the person who detects the deviation (column 2), the type of distinctive features (column 3) and in which IQC-Card they are documented (column 4) are also noted. As soon as the cause is known, it is documented in column 5 with the measured taken (column 6). The result of the measures introduced is entered together with date (date 7), the result of the measures (column 8) and the name of the person who determined the result (column 9). — printed p.67 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'abweichungen') AND w.code = 'ATV-A-704E-12' AND s.code = 'ATV-A-704E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'abweichungen_count', 'Anzahl protokollierter Abweichungen (aus dem Register)', 'number', NULL, false, 'Annex A, IQC-Card 11', 'Plan 3: Ausgabe der Gleichung ATV-A-704E-12-D1 (count_rows über abweichungen; leeres Register ⇒ 0). Eine 0 bedeutet „keine Abweichung protokolliert“, nicht „keine Abweichung aufgetreten“ — CR-028 hat heute eine LEERE Bedingung (atv_a704e-G-7).', 'imported_unverified', 'Here, the date of the deviation is put down in column 1. The name of the person who detects the deviation (column 2), the type of distinctive features (column 3) and in which IQC-Card they are documented (column 4) are also noted. As soon as the cause is known, it is documented in column 5 with the measured taken (column 6). The result of the measures introduced is entered together with date (date 7), the result of the measures (column 8) and the name of the person who determined the result (column 9). — printed p.67 [prod verification_quote — EV, unverified: ATV-A-704E has NO transcript (scanned PDF without text layer); jeder gedruckte IGC-Karten-Wert ist ein Freigabepunkt atv_a704e-U-1 … U-6]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'abweichungen_count') AND w.code = 'ATV-A-704E-12' AND s.code = 'ATV-A-704E';
COMMIT;
